import React, { useState, useCallback } from 'react';
import { detectAdversarial, correctPrompt, queryLLM } from './services/api';
import InputBox from './components/InputBox';
import StatusBox from './components/StatusBox';
import CorrectedBox from './components/CorrectedBox';
import ResponseBox from './components/ResponseBox';

const App = () => {
  // State management
  const [state, setState] = useState({
    inputText: '',
    status: { message: 'Ready', type: 'info' }, // types: info, success, warning, error
    correctedPrompt: null,
    llmResponse: null,
    isLoading: false,
    error: null
  });

  // Memoized styles
  const styles = {
    appContainer: {
      maxWidth: 'min(800px, 90vw)',
      margin: '0 auto',
      padding: '2rem',
      fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
      minHeight: '100vh',
      display: 'flex',
      flexDirection: 'column',
      gap: '1.5rem'
    },
    heading: {
      color: '#2c3e50',
      textAlign: 'center',
      marginBottom: '1rem'
    }
  };

  // Process the user's prompt
  const handleSubmit = useCallback(async (e) => {
    e.preventDefault();
    const { inputText } = state;
    
    if (!inputText.trim()) {
      setState(prev => ({
        ...prev,
        status: { message: 'Please enter a prompt', type: 'warning' }
      }));
      return;
    }

    setState(prev => ({
      ...prev,
      isLoading: true,
      status: { message: 'Analyzing prompt...', type: 'info' },
      correctedPrompt: null,
      llmResponse: null,
      error: null
    }));

    try {
      // Step 1: Detect adversarial content
      const detectionResult = await detectAdversarial(inputText);
      
      if (detectionResult.isAdversarial) {
        setState(prev => ({
          ...prev,
          status: { message: 'Adversarial content detected. Correcting...', type: 'warning' }
        }));

        // Step 2: Correct the prompt
        const correctionResult = await correctPrompt(inputText);
        
        // Step 3: Query LLM with corrected prompt
        const llmResult = await queryLLM(correctionResult.correctedPrompt);
        
        setState(prev => ({
          ...prev,
          correctedPrompt: correctionResult.correctedPrompt,
          llmResponse: llmResult.response,
          status: { 
            message: 'Used corrected prompt (original was adversarial)', 
            type: 'success' 
          },
          isLoading: false
        }));
      } else {
        // Query LLM directly if clean
        const llmResult = await queryLLM(inputText);
        
        setState(prev => ({
          ...prev,
          llmResponse: llmResult.response,
          status: { message: 'Clean prompt processed', type: 'success' },
          isLoading: false
        }));
      }
    } catch (error) {
      console.error('Processing error:', error);
      setState(prev => ({
        ...prev,
        status: { 
          message: error.response?.data?.message || 'Failed to process request', 
          type: 'error' 
        },
        error: error.message,
        isLoading: false
      }));
    }
  }, [state.inputText]);

  return (
    <div style={styles.appContainer}>
      <h1 style={styles.heading}>Adversarial Prompt Protector</h1>
      
      <InputBox
        value={state.inputText}
        onChange={(e) => setState(prev => ({ ...prev, inputText: e.target.value }))}
        onSubmit={handleSubmit}
        isLoading={state.isLoading}
        disabled={state.isLoading}
      />

      <StatusBox 
        status={state.status} 
        error={state.error} 
      />
      
      {state.correctedPrompt && (
        <CorrectedBox 
          original={state.inputText} 
          corrected={state.correctedPrompt} 
        />
      )}
      
      {state.llmResponse && (
        <ResponseBox 
          response={state.llmResponse} 
          isLoading={state.isLoading} 
        />
      )}
    </div>
  );
};

export default App;
